const nodes = {
  chat:['Chat adapter','Poruka je ulazni događaj. Adapter preuzima tekst i kontekst, dodeljuje event ID, ali ne donosi odluku o prioritetu niti dobija neograničene dozvole.'],
  cli:['CLI adapter','Terminal poziva isti posao kao chat: ticket ID, komanda i opcioni kontekst. Lokalni run može prvo raditi u read-only režimu.'],
  schedule:['Scheduler','Cron ili platform scheduler šalje događaj sa vrstom posla i idempotency ključem. Jutarnji scan i noćni review koriste isti engine.'],
  inbox:['Ulaz i trijaža','Normalizuj prijavu, spoji duplikate, proveri da li postoji dokaz i napiši strukturirani tiket. Ako nema reprodukcije, tiket ostaje u statusu needs-info.'],
  queue:['Prioritet i red','Prioritet je pravilo zasnovano na uticaju, hitnosti, učestalosti, sigurnosti i pouzdanosti signala. Agent sme da predloži; politika odlučuje šta može automatski u red.'],
  worker:['Radnik u sandboxu','Radnik dobija jedan izolovan worktree i ograničene alate. Kreće od reprodukcije, zatim planira malu ispravnu promenu i ostavlja trag koraka.'],
  verify:['Verifikacija','Uporedi stvarni ishod sa kriterijumom: testovi, lint, browser tok preko Playwrighta ili computer-use, snimak i log. Nedostupan dokaz znači neprovereno.'],
  review:['Nezavisan review','Drugi prolaz čita diff i poslednji commit, proverava blast radius, sigurnost i neuspešne testove. Nalaz mora imati putanju, dokaz i predlog provere.'],
  gate:['Merge gate','Kod unapred dozvoljenih niskorizičnih promena gate može spojiti PR ako su svi uslovi sveži i uspešni. Osetljive promene i konfliktni dokazi idu čoveku.'],
  observe:['Posmatranje i učenje','Nakon mergea prati metrike, greške i korisnički tok. Ako se problem vrati: rollback, novi tiket i eval slučaj. Ponovljena greška postaje test ili guardrail.']
};
const nodeDetail=document.getElementById('node-detail');
function showNode(key){document.querySelectorAll('[data-node]').forEach(x=>x.classList.toggle('selected',x.dataset.node===key));const [name,description]=nodes[key];nodeDetail.innerHTML=`<b>${name}</b><p>${description}</p>`}
document.querySelectorAll('[data-node]').forEach(button=>button.addEventListener('click',()=>showNode(button.dataset.node)));showNode('inbox');

const scenarios={
 bug:{meta:'CHAT → TIKET → ISPRAVKA',title:'Korisnik ne može da sačuva profil',intro:'Prijava iz chata kaže da dugme „Sačuvaj“ ponekad ne reaguje. Sistem mora razdvojiti signal od pretpostavke.',ticket:{id:'BUG-042',signal:'3 prijave / 24 h',priority:'P2 · srednji uticaj',acceptance:'Playwright ponavlja grešku na main, prolazi posle izmene; nema regresije u validaciji forme.'},steps:[['Intake','Sačuvaj originalni izvor, vreme i event ID.'],['Reprodukcija','Playwright otvara profil, menja polje i proverava da li zahtev stiže.'],['Trijaža','Spoji duplikate; izračunaj prioritet uz broj pogođenih korisnika.'],['Rad u izolaciji','Agent otvara worktree, menja kod i dodaje regresioni test.'],['Verifikacija','Test, build i browser tok daju artefakte pre/posle.'],['Review i gate','Nezavisan review proverava diff. Zbog UI promene: čovek potvrđuje merge.']],outcome:'Predlog PR-a je spreman; merge čeka pregled dokaza i ljudsku potvrdu.'},
 pr:{meta:'GITHUB EVENT → REVIEW → ODLUKA',title:'Stigao je PR za autentifikaciju',intro:'PR menja tok prijave. Čak i ako svi testovi prolaze, promenu treba pregledati prema njenom riziku.',ticket:{id:'PR-118',signal:'Novi commit / webhook',priority:'Visok rizik · auth',acceptance:'Provereni testovi i negativni scenariji; nalaz vezan za poslednji commit.'},steps:[['Webhook','Validiraj izvor, potpis i commit SHA; izbegni dupli run.'],['Razumevanje diffa','Identifikuj auth granicu, testove i pogođene putanje.'],['Nezavisan review','Traži eskalaciju privilegija, greške sesije i pogrešne pretpostavke.'],['Dinamička provera','Pokreni negativne testove i browser prijavu/odjavu.'],['Nalaz','Komentar mora pokazati liniju, scenario i dokaz.'],['Merge gate','Auth promena ostaje uz čoveka čak i kad su checks zeleni.']],outcome:'Automatski review daje dokaz i blokira auto-merge; vlasnik auth oblasti odlučuje.'},
 scan:{meta:'SCHEDULE 09:00 → TRIJAŽA → RED',title:'Jutarnji pregled signala',intro:'Zakazani posao čita promene od poslednjeg uspešnog runa: greške, neobrađene tikete i CI kvarove.',ticket:{id:'SCAN-2026-11-15',signal:'12 signala / 4 duplikata',priority:'1 P1 · 3 P2 · ostalo backlog',acceptance:'Svaki P1 ima izvor i vlasnika; bez ponovljenih tiketa; izveštaj s linkovima.'},steps:[['Okidač','Scheduler emituje događaj; idempotency ključ sprečava dupliranje.'],['Sakupljanje','Učitaj samo novije signale i postojeće tikete.'],['Deduplikacija','Spoji iste stack traceove i prijave iste greške.'],['Rangiranje','P1 za uticaj na mnogo korisnika i aktivnu regresiju.'],['Dodela','Jasne P2 ispravke idu u red; nejasne traže više podataka.'],['Izveštaj','Zabeleži odluke, trošak i odbijene signale.']],outcome:'Kreiran je pregled trijaže. Samo jasno definisani zadaci ulaze u radni red.'}
};
let scenario='bug',step=0;
const esc=value=>String(value).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
function renderScenario(){const s=scenarios[scenario];document.getElementById('sim-meta').textContent=s.meta;document.getElementById('sim-title').textContent=s.title;document.getElementById('sim-intro').textContent=s.intro;document.getElementById('ticket-content').innerHTML=`<dl><dt>ID</dt><dd>${esc(s.ticket.id)}</dd><dt>Signal</dt><dd>${esc(s.ticket.signal)}</dd><dt>Prioritet</dt><dd>${esc(s.ticket.priority)}</dd><dt>Acceptance</dt><dd>${esc(s.ticket.acceptance)}</dd></dl>`;document.getElementById('sim-steps').innerHTML=s.steps.map(([title,description],i)=>`<div class="sim-step ${i<step?'done':i===step?'current':''}"><span>${String(i+1).padStart(2,'0')}</span><div><b>${esc(title)}</b><p>${esc(description)}</p></div></div>`).join('');document.getElementById('sim-progress').textContent=`${step} / ${s.steps.length}`;const outcome=document.getElementById('sim-outcome');outcome.classList.toggle('success',step===s.steps.length);outcome.textContent=step===s.steps.length?s.outcome:step===0?'Klikni „Sledeći korak“ da vidiš kako sistem odlučuje.':`Završen korak ${step}. Sledeći: ${s.steps[step][0]}.`;document.getElementById('next-step').disabled=step===s.steps.length;document.getElementById('next-step').style.opacity=step===s.steps.length?'.5':'1';document.querySelectorAll('[data-scenario]').forEach(b=>{const active=b.dataset.scenario===scenario;b.classList.toggle('active',active);b.setAttribute('aria-selected',active)})}
document.querySelectorAll('[data-scenario]').forEach(b=>b.addEventListener('click',()=>{scenario=b.dataset.scenario;step=0;renderScenario()}));document.getElementById('next-step').addEventListener('click',()=>{if(step<scenarios[scenario].steps.length)step++;renderScenario()});document.getElementById('reset-sim').addEventListener('click',()=>{step=0;renderScenario()});renderScenario();

const taskSelect=document.getElementById('task-type');const risk=document.getElementById('risk'),clarity=document.getElementById('clarity'),volume=document.getElementById('volume');
function route(){const t=taskSelect.value,r=+risk.value,c=+clarity.value,v=+volume.value;document.getElementById('risk-value').textContent=r;document.getElementById('clarity-value').textContent=c;document.getElementById('volume-value').textContent=v;let tier,model,effort,why,example,escalation;
if(t==='classify'&&r<=2&&c>=3){tier='EKONOMIČNO';model='Luna ili DeepSeek Flash';effort='low / bez thinkinga';why='Uslov je jasan, izlaz može biti strogo strukturiran, a velik obim nagrađuje nisku cenu i latenciju.';example='Primer: izvuci komponentu, ozbiljnost i fingerprint duplikata iz bug prijave.';escalation='Ako validacija šeme padne ili je sigurnost klasifikacije niska, pošalji Solu na drugi prolaz.'}
else if(r>=4||c<=2||t==='architecture'){tier='ESKALACIJA';model='Astra ili Opus';effort=r===5||c===1?'high → xhigh uz eval':'high';why='Visok rizik ili nejasan problem traži dublju analizu i više nezavisnih provera. Model sam ne sme odobriti visokorizični merge.';example='Primer: analiza incidenta kroz više servisa ili dizajn promena u autorizaciji.';escalation='Ako i dalje nema reprodukcije ili su dokazi u sukobu, zaustavi automatizaciju i traži čoveka.'}
else if(t==='review'){tier='NEZAVISAN PREGLED';model='Sol ili Grok 4.6; drugi model po potrebi';effort=r>=3?'high':'medium';why='Review traži zaključivanje o posledicama diffa; drugi model je koristan samo ako nalaze proveravaš konkretnim testom.';example='Primer: reviewer proverava API contract, negativne slučajeve i poslednji commit SHA.';escalation='Nalaz bez reprodukcije označi kao hipotezu. Osetljiv kod šalji domenskom vlasniku.'}
else {tier=v>=4?'RADNI SLOJ / OPTIMIZUJ TROŠAK':'RADNI SLOJ';model=t==='debug'?'Sol ili Opus/Sonnet':'Sol, Sonnet ili Grok 4.6';effort=t==='debug'?'high':'medium';why='Jasan tehnički zadatak traži model koji pouzdano koristi alate. Veći obim opravdava benchmark i eventualni prelaz na jeftiniji model.';example=t==='debug'?'Primer: reprodukcija race conditiona i najmanja ispravna promena.':'Primer: tiketi s preciznim acceptance kriterijumima i automatskim testom.';escalation='Ako dva pokušaja ne poprave isti uzrok, promeni strategiju, dodaj kontekst ili eskaliraj model.'}
document.getElementById('route-tier').textContent=tier;document.getElementById('route-model').textContent=model;document.getElementById('route-effort').textContent=effort;document.getElementById('route-why').textContent=why;document.getElementById('route-examples').textContent=example;document.getElementById('route-escalation').textContent=escalation}
[taskSelect,risk,clarity,volume].forEach(x=>x.addEventListener('input',route));route();

const roadmap=[
 ['1','Napravi mapu jednog procesa','1 nedelja','Izaberi jedan repozitorijum i jedan tip buga. Nacrtaj događaje, status tiketa, vlasnika odluke i uslove za stop.','Možeš ručno proći od prijave do dokaza bez nejasnih koraka.'],
 ['2','Napiši agent-friendly repo','1–2 nedelje','Dodaj kratko uputstvo za pokretanje, mapu arhitekture, test komande, primere i pravila za granice modula.','Novi agent može da reprodukuje jedan bug bez usmenog objašnjenja.'],
 ['3','Izgradi verifikacioni skill','1 nedelja','Skriptuj launch, health check, browser/CLI tok, čuvanje artefakta i cleanup. Napravi mapu funkcija i njihovih dokaza.','Isti test radi lokalno i u izolovanom okruženju, ponovljivo.'],
 ['4','Dodaj intake, tiket i prioritete','1–2 nedelje','Normalizuj događaje, dedupliraj ih i koristi eksplicitnu šemu tiketa. Počni sa read-only ingestom i ljudskim potvrđivanjem.','Na 20 istorijskih prijava, prioritet i duplikati su uporedivi s ljudskim odlukama.'],
 ['5','Poveži radnika i PR','2 nedelje','Jedan ticket → jedan izolovani worktree → reprodukcija → izmena → test → draft PR s dokazima. Ograniči pokušaje i trošak.','Pet istorijskih tiketa daje proverljive PR-ove bez regressija.'],
 ['6','Uvedi nezavisan review i gate','1–2 nedelje','Odvojen reviewer, CI, risk klasifikacija i policy za merge. Auto-merge prvo samo za dokumentaciju i mehaničke izmene.','Nijedan visokorizični PR ne prolazi bez čoveka; svaki auto-merge ima rollback put.'],
 ['7','Dodaj schedule i outer loop','stalno','Planirani scanovi, posle-merge posmatranje, eval skup i nedeljno uklanjanje ponovljenih grešaka.','Meriš success rate, cost per successful ticket, vreme do mergea i regressije po promeni.']
];
document.getElementById('roadmap').innerHTML=roadmap.map(([n,title,time,work,gate],i)=>`<article class="roadmap-item ${i===0?'open':''}"><button class="roadmap-head" aria-expanded="${i===0?'true':'false'}"><span>${n.padStart(2,'0')}</span><b>${title}</b><small>${time}</small><span class="chevron">+</span></button><div class="roadmap-body"><div><label>ŠTA GRADIŠ</label><p>${work}</p></div><div><label>GATE ZA DALJE</label><p>${gate}</p></div></div></article>`).join('');document.querySelectorAll('.roadmap-head').forEach(button=>button.addEventListener('click',()=>{const item=button.parentElement;const open=item.classList.toggle('open');button.setAttribute('aria-expanded',open)}));

const sections=[...document.querySelectorAll('main section[id]')],links=[...document.querySelectorAll('.side-nav a')];const observer=new IntersectionObserver(entries=>{const visible=entries.filter(e=>e.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];if(visible)links.forEach(a=>a.classList.toggle('active',a.hash==='#'+visible.target.id))},{rootMargin:'-20% 0px -60% 0px',threshold:[0,.2,.5]});sections.forEach(s=>observer.observe(s));
